{"path":"src/features/search/utils/filterUsers.js","content":"// Filters users by username or full name (case-insensitive, trimmed query).
// An empty query returns all users.
export function filterUsersByQuery(users, query) {
  const searchTerm = query.trim().toLowerCase();
  if (!searchTerm) return users || [];
  return (users || []).filter((u) => {
    const uname = (u.username || "").toLowerCase();
    const fname = (u.full_name || "").toLowerCase();
    return uname.includes(searchTerm) || fname.includes(searchTerm);
  });
}
"}

